import pandas as pd
from sklearn.tree import DecisionTreeClassifier
from sklearn.metrics import accuracy_score

# 1. Load the dataset generated by the admin
input_filename = "ml_input_data.xlsx"
df = pd.read_excel(input_filename)

print("Data loaded successfully! Here is a preview:")
print(df.head(), "\n")

# 2. Preprocess the data
# Machine learning models need numbers, so we convert the text labels
df['Risk_Label'] = df['Actual_Risk'].map({'Low Risk': 0, 'High Risk': 1})

# Define features (X) and our target prediction (y)
X = df[['Credit_Score', 'Income_k']]
y = df['Risk_Label']

# 3. Train a Machine Learning model
model = DecisionTreeClassifier(random_state=42)
model.fit(X, y)

# 4. Make predictions to verify it works
predictions = model.predict(X)
accuracy = accuracy_score(y, predictions)

print("Model trained successfully!")
print(f"Accuracy on the training dataset: {accuracy * 100:.2f}%")
